"use client";
import { useState } from "react";
import { motion } from "motion/react";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryIndex,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface ImageFollowListItem extends GalleryInternalItem {}
export interface ImageFollowListProps extends GalleryInternalProps {
  items: readonly ImageFollowListItem[];
  imageWidth?: number;
  imageHeight?: number;
  duration?: number;
  offset?: number;
}
export function ImageFollowList(props: ImageFollowListProps) {
  const {
    items,
    imageWidth = 200,
    imageHeight = 150,
    duration = 0.3,
    offset = 24,
    height = 640,
    label = "Projects",
    className = "",
    style,
    onSelect,
    renderCaption,
  } = props;
  const env = useGalleryEnvironment();
  const { current, choose } = useGalleryIndex(props);
  const [visible, setVisible] = useState(false);
  const [point, setPoint] = useState({ x: 350, y: 140 });
  const width = Math.min(imageWidth, env.size.width * 0.5);
  const move = (clientX: number, clientY: number) => {
    const box = env.ref.current?.getBoundingClientRect();
    if (!box) return;
    setPoint({
      x: Math.max(8, Math.min(clientX - box.left + offset, box.width - width - 8)),
      y: Math.max(
        8,
        Math.min(clientY - box.top - imageHeight * 0.65, box.height - imageHeight - 8),
      ),
    });
  };
  return (
    <div
      ref={env.ref}
      className={`z-ag z-ag-list ${className}`}
      data-gallery="image-follow-list"
      data-index={current}
      data-preview-visible={visible}
      role="region"
      aria-label={label}
      onPointerMove={(e) => {
        if (e.pointerType !== "touch") move(e.clientX, e.clientY);
      }}
      onPointerLeave={() => setVisible(false)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setVisible(false);
      }}
      style={galleryStyle(height, style)}
    >
      <GalleryInternalStyles />
      {items.map((item, i) => (
        <button
          type="button"
          key={item.id}
          className="z-ag-row"
          data-gallery-card={i}
          data-active={visible && current === i}
          onPointerEnter={(e) => {
            if (e.pointerType !== "touch") {
              choose(i);
              setVisible(true);
              move(e.clientX, e.clientY);
            }
          }}
          onFocus={(e) => {
            choose(i);
            setVisible(true);
            const box = e.currentTarget.getBoundingClientRect();
            move(box.right - width - offset - 24, box.top + box.height / 2);
          }}
          onClick={(e) => {
            choose(i);
            setVisible(true);
            const box = e.currentTarget.getBoundingClientRect();
            move(box.right - width - offset - 24, box.top + box.height / 2);
            onSelect?.(item, i);
          }}
        >
          <span className="z-ag-row-label">{renderCaption?.(item, i) ?? item.title}</span>
        </button>
      ))}
      {items[current] && (
        <motion.div
          className="z-ag-follow-preview"
          aria-hidden="true"
          initial={false}
          animate={{ x: point.x, y: point.y, opacity: visible ? 1 : 0, scale: visible ? 1 : 0.85 }}
          transition={{ duration: env.reduced ? 0 : duration, ease: [0.16, 1, 0.3, 1] }}
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width,
            height: imageHeight,
            borderRadius: 6,
            overflow: "hidden",
            pointerEvents: "none",
            zIndex: 20,
          }}
        >
          <GalleryInternalImage item={items[current]} />
        </motion.div>
      )}
    </div>
  );
}
